import 'dart:async';import 'dart:ui';import 'package:flutter/material.dart';import '../../../core/theme/catus_theme.dart';import '../data/ai_assistant_service.dart';/// AI Assistant Screen — Premium chat-style interface for offline survival intelligence.class AIAssistantScreen extends StatefulWidget {  const AIAssistantScreen({super.key});  @override  State<AIAssistantScreen> createState() => _AIAssistantScreenState();}class _AIAssistantScreenState extends State<AIAssistantScreen>    with TickerProviderStateMixin {  final _controller = TextEditingController();  final _scrollController = ScrollController();  final _aiService = AIAssistantService();  final List<_ChatMessage> _messages = [];  final _focusNode = FocusNode();  bool _isTyping = false;  bool _triageMode = false;  final List<String> _triageSymptoms = [];  bool _showScrollToBottom = false;  late AnimationController _pulseController;  late AnimationController _welcomeController;  late Animation<double> _welcomeFade;  late Animation<Offset> _welcomeSlide;  @override  void initState() {    super.initState();    _aiService.initialize();    _pulseController = AnimationController(      vsync: this,      duration: const Duration(seconds: 2),    )..repeat(reverse: true);    _welcomeController = AnimationController(      vsync: this,      duration: const Duration(milliseconds: 800),    );    _welcomeFade = CurvedAnimation(      parent: _welcomeController,      curve: Curves.easeOut,    );    _welcomeSlide = Tween<Offset>(      begin: const Offset(0, 0.15),      end: Offset.zero,    ).animate(CurvedAnimation(      parent: _welcomeController,      curve: Curves.easeOutCubic,    ));    _scrollController.addListener(_onScroll);    // Add welcome message with delay for animation    Future.delayed(const Duration(milliseconds: 300), () {      if (mounted) {        setState(() {          _messages.add(_ChatMessage(            text: 'I\'m your offline AI survival assistant. Ask me about:\n\n'                '🏥  First Aid — CPR, bleeding, fractures\n'                '💧  Water — purification methods\n'                '🔥  Fire — starting techniques\n'                '🏕️  Shelter — emergency building\n'                '🧭  Navigation — without GPS\n'                '📡  Signaling — rescue protocols\n'                '🌡️  Hypothermia — cold treatment\n'                '🐍  Snakebite — emergency response',            isAI: true,            timestamp: DateTime.now(),          ));        });        _welcomeController.forward();      }    });  }  void _onScroll() {    if (!_scrollController.hasClients) return;    final showBtn = _scrollController.offset <        _scrollController.position.maxScrollExtent - 100;    if (showBtn != _showScrollToBottom) {      setState(() => _showScrollToBottom = showBtn);    }  }  void _sendMessage() {    final text = _controller.text.trim();    if (text.isEmpty) return;    setState(() {      _messages.add(_ChatMessage(        text: text,        isAI: false,        timestamp: DateTime.now(),      ));      _isTyping = true;    });    _controller.clear();    _scrollToBottom();    // Simulate AI thinking with a brief delay    Future.delayed(Duration(milliseconds: 400 + (text.length * 3).clamp(0, 800)), () {      if (!mounted) return;      if (_triageMode) {        _handleTriageInput(text);      } else {        final response = _aiService.ask(text);        setState(() {          _isTyping = false;          _messages.add(_ChatMessage(            text: response.answer,            isAI: true,            confidence: response.confidence,            category: response.category,            timestamp: DateTime.now(),          ));        });      }      _scrollToBottom();    });  }  void _handleTriageInput(String text) {    _triageSymptoms.add(text);    if (_triageSymptoms.length < 3) {      setState(() {        _isTyping = false;        _messages.add(_ChatMessage(          text: 'Symptom "$text" noted. ${3 - _triageSymptoms.length} more to go, '              'or type "done" to get triage results.',          isAI: true,          category: 'medical',          timestamp: DateTime.now(),        ));      });    } else {      _finishTriage();    }    if (text.toLowerCase() == 'done' && _triageSymptoms.isNotEmpty) {      _triageSymptoms.removeLast(); // remove "done"      _finishTriage();    }  }  void _finishTriage() {    final result = _aiService.triage(_triageSymptoms);    final priorityEmoji = result.priority == 'RED'        ? '🔴'        : result.priority == 'YELLOW'            ? '🟡'            : '🟢';    setState(() {      _isTyping = false;      _triageMode = false;      _messages.add(_ChatMessage(        text: '$priorityEmoji TRIAGE RESULT: ${result.priority} PRIORITY\n'            'Score: ${result.score}/15\n\n'            '${result.actions.isNotEmpty ? result.actions.join('\n') : 'No critical actions needed.'}',        isAI: true,        category: 'medical',        confidence: 0.9,        isTriage: true,        triagePriority: result.priority,        timestamp: DateTime.now(),      ));      _triageSymptoms.clear();    });  }  void _startTriage() {    setState(() {      _triageMode = true;      _triageSymptoms.clear();      _messages.add(_ChatMessage(        text: '🏥 MEDICAL TRIAGE MODE\n\n'            'Describe the patient\'s symptoms one at a time.\n'            'Examples: "chest pain", "difficulty breathing", "deep cut"\n\n'            'I\'ll assess the priority level when you\'re done.\n'            'Type "done" when finished.',        isAI: true,        category: 'medical',        timestamp: DateTime.now(),      ));    });    _scrollToBottom();  }  void _scrollToBottom() {    WidgetsBinding.instance.addPostFrameCallback((_) {      if (_scrollController.hasClients) {        _scrollController.animateTo(          _scrollController.position.maxScrollExtent,          duration: const Duration(milliseconds: 400),          curve: Curves.easeOutCubic,        );      }    });  }  @override  void dispose() {    _pulseController.dispose();    _welcomeController.dispose();    _scrollController.dispose();    _controller.dispose();    _focusNode.dispose();    super.dispose();  }  @override  Widget build(BuildContext context) {    return Scaffold(      backgroundColor: CatusTheme.background,      body: Stack(        children: [          // Background gradient blobs          Positioned(            top: -60,            right: -40,            child: AnimatedBuilder(              animation: _pulseController,              builder: (_, __) => Container(                width: 200,                height: 200,                decoration: BoxDecoration(                  shape: BoxShape.circle,                  gradient: RadialGradient(                    colors: [                      CatusTheme.accent.withValues(alpha: 0.06 + _pulseController.value * 0.04),                      Colors.transparent,                    ],                  ),                ),              ),            ),          ),          Positioned(            bottom: 100,            left: -60,            child: Container(              width: 160,              height: 160,              decoration: BoxDecoration(                shape: BoxShape.circle,                gradient: RadialGradient(                  colors: [                    CatusTheme.gradientCool.withValues(alpha: 0.05),                    Colors.transparent,                  ],                ),              ),            ),          ),          // Main content          Column(            children: [              _buildAppBar(),              _buildTopicChips(),              Expanded(child: _buildMessageList()),              if (_isTyping) _buildTypingIndicator(),              _buildInput(),            ],          ),          // Scroll-to-bottom FAB          if (_showScrollToBottom && _messages.length > 5)            Positioned(              bottom: 80,              right: 16,              child: GestureDetector(                onTap: _scrollToBottom,                child: Container(                  width: 40,                  height: 40,                  decoration: BoxDecoration(                    color: CatusTheme.surfaceElevated,                    shape: BoxShape.circle,                    border: Border.all(color: CatusTheme.glassBorder),                    boxShadow: [                      BoxShadow(                        color: Colors.black.withValues(alpha: 0.3),                        blurRadius: 8,                        offset: const Offset(0, 2),                      ),                    ],                  ),                  child: const Icon(Icons.keyboard_arrow_down,                      color: CatusTheme.textSecondary, size: 22),                ),              ),            ),        ],      ),    );  }  // ─── App Bar ───  Widget _buildAppBar() {    return ClipRRect(      child: BackdropFilter(        filter: ImageFilter.blur(sigmaX: 16, sigmaY: 16),        child: Container(          padding: EdgeInsets.only(            top: MediaQuery.of(context).padding.top + 8,            left: 16,            right: 16,            bottom: 12,          ),          decoration: BoxDecoration(            color: CatusTheme.surface.withValues(alpha: 0.85),            border: const Border(              bottom: BorderSide(color: CatusTheme.glassBorder, width: 0.5),            ),          ),          child: Row(            children: [              // Back button              GestureDetector(                onTap: () => Navigator.of(context).pop(),                child: Container(                  width: 36,                  height: 36,                  decoration: BoxDecoration(                    color: CatusTheme.surfaceLight,                    borderRadius: BorderRadius.circular(10),                    border: Border.all(color: CatusTheme.glassBorder),                  ),                  child: const Icon(Icons.arrow_back_ios_new,                      size: 14, color: CatusTheme.textSecondary),                ),              ),              const SizedBox(width: 12),              // AI avatar with pulse              AnimatedBuilder(                animation: _pulseController,                builder: (_, __) => Container(                  width: 38,                  height: 38,                  decoration: BoxDecoration(                    shape: BoxShape.circle,                    gradient: const LinearGradient(                      colors: [CatusTheme.accent, CatusTheme.gradientEnd],                      begin: Alignment.topLeft,                      end: Alignment.bottomRight,                    ),                    boxShadow: [                      BoxShadow(                        color: CatusTheme.accent                            .withValues(alpha: 0.2 + _pulseController.value * 0.15),                        blurRadius: 10 + _pulseController.value * 6,                        spreadRadius: _pulseController.value * 2,                      ),                    ],                  ),                  child: const Icon(Icons.psychology, color: Colors.white, size: 20),                ),              ),              const SizedBox(width: 10),              // Title + status              Expanded(                child: Column(                  crossAxisAlignment: CrossAxisAlignment.start,                  children: [                    const Text(                      'Survival AI',                      style: TextStyle(                        color: CatusTheme.textPrimary,                        fontSize: 16,                        fontWeight: FontWeight.w600,                      ),                    ),                    Row(                      children: [                        Container(                          width: 6,                          height: 6,                          decoration: const BoxDecoration(                            color: CatusTheme.safeGreen,                            shape: BoxShape.circle,                          ),                        ),                        const SizedBox(width: 4),                        const Text(                          'Offline • Ready',                          style: TextStyle(                              color: CatusTheme.safeGreen, fontSize: 11),                        ),                      ],                    ),                  ],                ),              ),              // Triage button              GestureDetector(                onTap: _triageMode ? null : _startTriage,                child: Container(                  padding:                      const EdgeInsets.symmetric(horizontal: 10, vertical: 6),                  decoration: BoxDecoration(                    gradient: _triageMode                        ? null                        : const LinearGradient(                            colors: [Color(0xFFEF4444), Color(0xFFDC2626)]),                    color: _triageMode                        ? CatusTheme.sosRed.withValues(alpha: 0.2)                        : null,                    borderRadius: BorderRadius.circular(10),                    border: _triageMode                        ? Border.all(color: CatusTheme.sosRed.withValues(alpha: 0.4))                        : null,                  ),                  child: Row(                    mainAxisSize: MainAxisSize.min,                    children: [                      Icon(                        Icons.medical_services,                        size: 13,                        color:                            _triageMode ? CatusTheme.sosRed : Colors.white,                      ),                      const SizedBox(width: 4),                      Text(                        _triageMode ? 'Active' : 'Triage',                        style: TextStyle(                          fontSize: 11,                          fontWeight: FontWeight.w600,                          color: _triageMode                              ? CatusTheme.sosRed                              : Colors.white,                        ),                      ),                    ],                  ),                ),              ),            ],          ),        ),      ),    );  }  // ─── Topic Chips ───  Widget _buildTopicChips() {    final topics = [      const _TopicItem('🏥', 'First Aid', CatusTheme.sosRed),      const _TopicItem('💧', 'Water', Color(0xFF3B82F6)),      const _TopicItem('🔥', 'Fire', CatusTheme.warningYellow),      const _TopicItem('🏕️', 'Shelter', CatusTheme.safeGreen),      const _TopicItem('🧭', 'Navigation', Color(0xFF8B5CF6)),      const _TopicItem('📡', 'Signaling', Color(0xFFF97316)),      const _TopicItem('🌡️', 'Hypothermia', Color(0xFF06B6D4)),      const _TopicItem('🐍', 'Snakebite', Color(0xFFEC4899)),    ];    return Container(      height: 50,      margin: const EdgeInsets.only(top: 4),      child: ListView.builder(        scrollDirection: Axis.horizontal,        padding: const EdgeInsets.symmetric(horizontal: 12),        itemCount: topics.length,        itemBuilder: (context, i) => _buildTopicChip(topics[i]),      ),    );  }  Widget _buildTopicChip(_TopicItem topic) {    return GestureDetector(      onTap: () {        _controller.text = topic.label;        _sendMessage();      },      child: Container(        margin: const EdgeInsets.only(right: 8, top: 4, bottom: 4),        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),        decoration: BoxDecoration(          color: topic.color.withValues(alpha: 0.08),          borderRadius: BorderRadius.circular(20),          border: Border.all(color: topic.color.withValues(alpha: 0.2)),        ),        child: Row(          mainAxisSize: MainAxisSize.min,          children: [            Text(topic.emoji, style: const TextStyle(fontSize: 13)),            const SizedBox(width: 5),            Text(              topic.label,              style: TextStyle(                fontSize: 12,                fontWeight: FontWeight.w500,                color: topic.color,              ),            ),          ],        ),      ),    );  }  // ─── Message List ───  Widget _buildMessageList() {    return ListView.builder(      controller: _scrollController,      padding: const EdgeInsets.fromLTRB(12, 8, 12, 8),      itemCount: _messages.length,      itemBuilder: (context, i) {        final msg = _messages[i];        final isFirst = i == 0;        // Staggered entry animation via SlideTransition on welcome        if (isFirst && msg.isAI) {          return SlideTransition(            position: _welcomeSlide,            child: FadeTransition(              opacity: _welcomeFade,              child: _buildBubble(msg),            ),          );        }        return _buildBubble(msg);      },    );  }  Widget _buildBubble(_ChatMessage msg) {    final isAI = msg.isAI;    final isTriage = msg.isTriage;    return Align(      alignment: isAI ? Alignment.centerLeft : Alignment.centerRight,      child: Container(        margin: EdgeInsets.only(          top: 6,          bottom: 6,          left: isAI ? 0 : 52,          right: isAI ? 52 : 0,        ),        child: Column(          crossAxisAlignment:              isAI ? CrossAxisAlignment.start : CrossAxisAlignment.end,          children: [            // Bubble            Container(              padding: const EdgeInsets.all(14),              decoration: BoxDecoration(                color: isTriage                    ? _triageColor(msg.triagePriority).withValues(alpha: 0.1)                    : isAI                        ? CatusTheme.surfaceLight                        : CatusTheme.accent.withValues(alpha: 0.15),                borderRadius: BorderRadius.only(                  topLeft: const Radius.circular(18),                  topRight: const Radius.circular(18),                  bottomLeft: Radius.circular(isAI ? 4 : 18),                  bottomRight: Radius.circular(isAI ? 18 : 4),                ),                border: Border.all(                  color: isTriage                      ? _triageColor(msg.triagePriority).withValues(alpha: 0.25)                      : isAI                          ? CatusTheme.glassBorder                          : CatusTheme.accent.withValues(alpha: 0.2),                  width: 0.5,                ),                boxShadow: [                  BoxShadow(                    color: Colors.black.withValues(alpha: 0.12),                    blurRadius: 6,                    offset: const Offset(0, 2),                  ),                ],              ),              child: Column(                crossAxisAlignment: CrossAxisAlignment.start,                children: [                  // Category badge                  if (isAI && msg.category != null) _buildCategoryBadge(msg),                  // Message text                  Text(                    msg.text,                    style: TextStyle(                      color: CatusTheme.textPrimary,                      fontSize: 13.5,                      height: 1.5,                      fontWeight: isTriage ? FontWeight.w500 : FontWeight.w400,                    ),                  ),                  // Confidence meter                  if (isAI && msg.confidence != null && msg.confidence! > 0)                    _buildConfidenceMeter(msg.confidence!),                ],              ),            ),            // Timestamp            Padding(              padding: const EdgeInsets.only(top: 4, left: 4, right: 4),              child: Text(                _formatTime(msg.timestamp),                style: const TextStyle(                  color: CatusTheme.textMuted,                  fontSize: 10,                ),              ),            ),          ],        ),      ),    );  }  Widget _buildCategoryBadge(_ChatMessage msg) {    final cat = msg.category!;    final isMedical = cat == 'medical';    final color = isMedical ? CatusTheme.sosRed : CatusTheme.safeGreen;    final icon = isMedical ? Icons.medical_services : Icons.park;    final label = isMedical ? 'Medical' : 'Survival';    return Container(      margin: const EdgeInsets.only(bottom: 8),      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),      decoration: BoxDecoration(        color: color.withValues(alpha: 0.12),        borderRadius: BorderRadius.circular(6),        border: Border.all(color: color.withValues(alpha: 0.2)),      ),      child: Row(        mainAxisSize: MainAxisSize.min,        children: [          Icon(icon, size: 11, color: color),          const SizedBox(width: 4),          Text(            label,            style: TextStyle(                fontSize: 10, fontWeight: FontWeight.w600, color: color),          ),        ],      ),    );  }  Widget _buildConfidenceMeter(double confidence) {    final pct = (confidence * 100).round();    final color = confidence >= 0.8        ? CatusTheme.safeGreen        : confidence >= 0.5            ? CatusTheme.warningYellow            : CatusTheme.sosRed;    return Padding(      padding: const EdgeInsets.only(top: 10),      child: Row(        mainAxisSize: MainAxisSize.min,        children: [          Icon(Icons.verified, size: 11, color: color.withValues(alpha: 0.7)),          const SizedBox(width: 5),          SizedBox(            width: 60,            height: 4,            child: ClipRRect(              borderRadius: BorderRadius.circular(2),              child: LinearProgressIndicator(                value: confidence,                backgroundColor: CatusTheme.surfaceElevated,                valueColor: AlwaysStoppedAnimation(color),              ),            ),          ),          const SizedBox(width: 5),          Text(            '$pct%',            style: TextStyle(                fontSize: 10,                color: color.withValues(alpha: 0.8),                fontWeight: FontWeight.w600),          ),        ],      ),    );  }  // ─── Typing Indicator ───  Widget _buildTypingIndicator() {    return Align(      alignment: Alignment.centerLeft,      child: Container(        margin: const EdgeInsets.only(left: 12, bottom: 4),        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),        decoration: BoxDecoration(          color: CatusTheme.surfaceLight,          borderRadius: BorderRadius.circular(18),          border: Border.all(color: CatusTheme.glassBorder, width: 0.5),        ),        child: Row(          mainAxisSize: MainAxisSize.min,          children: [            _TypingDot(delay: 0, controller: _pulseController),            const SizedBox(width: 4),            _TypingDot(delay: 0.2, controller: _pulseController),            const SizedBox(width: 4),            _TypingDot(delay: 0.4, controller: _pulseController),            const SizedBox(width: 8),            Text(              _triageMode ? 'Assessing...' : 'Analyzing...',              style: const TextStyle(                color: CatusTheme.textMuted,                fontSize: 11,                fontStyle: FontStyle.italic,              ),            ),          ],        ),      ),    );  }  // ─── Input Field ───  Widget _buildInput() {    return ClipRRect(      child: BackdropFilter(        filter: ImageFilter.blur(sigmaX: 12, sigmaY: 12),        child: Container(          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),          decoration: BoxDecoration(            color: CatusTheme.surface.withValues(alpha: 0.9),            border: const Border(              top: BorderSide(color: CatusTheme.glassBorder, width: 0.5),            ),          ),          child: SafeArea(            top: false,            child: Row(              children: [                // Input field                Expanded(                  child: Container(                    decoration: BoxDecoration(                      color: CatusTheme.surfaceLight,                      borderRadius: BorderRadius.circular(24),                      border: Border.all(color: CatusTheme.glassBorder),                    ),                    child: Row(                      children: [                        Expanded(                          child: TextField(                            controller: _controller,                            focusNode: _focusNode,                            style: const TextStyle(                              color: CatusTheme.textPrimary,                              fontSize: 14,                            ),                            decoration: InputDecoration(                              hintText: _triageMode                                  ? 'Describe a symptom...'                                  : 'Ask a survival question...',                              hintStyle: const TextStyle(                                  color: CatusTheme.textMuted, fontSize: 13),                              border: InputBorder.none,                              contentPadding: const EdgeInsets.symmetric(                                  horizontal: 16, vertical: 10),                            ),                            onSubmitted: (_) => _sendMessage(),                            textInputAction: TextInputAction.send,                          ),                        ),                      ],                    ),                  ),                ),                const SizedBox(width: 8),                // Send button                GestureDetector(                  onTap: _sendMessage,                  child: Container(                    width: 44,                    height: 44,                    decoration: BoxDecoration(                      gradient: const LinearGradient(                        colors: [CatusTheme.gradientStart, CatusTheme.gradientEnd],                        begin: Alignment.topLeft,                        end: Alignment.bottomRight,                      ),                      shape: BoxShape.circle,                      boxShadow: [                        BoxShadow(                          color: CatusTheme.accent.withValues(alpha: 0.35),                          blurRadius: 10,                          offset: const Offset(0, 3),                        ),                      ],                    ),                    child: const Icon(Icons.send_rounded,                        size: 19, color: Colors.white),                  ),                ),              ],            ),          ),        ),      ),    );  }  // ─── Helpers ───  Color _triageColor(String? priority) {    switch (priority) {      case 'RED':        return CatusTheme.sosRed;      case 'YELLOW':        return CatusTheme.warningYellow;      default:        return CatusTheme.safeGreen;    }  }  String _formatTime(DateTime? dt) {    if (dt == null) return '';    final h = dt.hour.toString().padLeft(2, '0');    final m = dt.minute.toString().padLeft(2, '0');    return '$h:$m';  }}// ─── Data Models ───class _ChatMessage {  final String text;  final bool isAI;  final double? confidence;  final String? category;  final DateTime? timestamp;  final bool isTriage;  final String? triagePriority;  _ChatMessage({    required this.text,    required this.isAI,    this.confidence,    this.category,    this.timestamp,    this.isTriage = false,    this.triagePriority,  });}class _TopicItem {  final String emoji;  final String label;  final Color color;  const _TopicItem(this.emoji, this.label, this.color);}// ─── Typing Dot Animation ───class _TypingDot extends StatelessWidget {  final double delay;  final AnimationController controller;  const _TypingDot({required this.delay, required this.controller});  @override  Widget build(BuildContext context) {    return AnimatedBuilder(      animation: controller,      builder: (_, __) {        // Create staggered bounce via phase offset        final t = (controller.value + delay) % 1.0;        final scale = 0.5 + (t < 0.5 ? t : 1.0 - t) * 1.0;        return Container(          width: 7 * scale,          height: 7 * scale,          decoration: BoxDecoration(            color: CatusTheme.accent.withValues(alpha: 0.4 + scale * 0.4),            shape: BoxShape.circle,          ),        );      },    );  }}